(@set02_exam_id,'SPEAKING','SPEAK_REPEAT','Listen to the sentence and repeat it aloud as clearly as possible. Record your answer.','The laboratory will be closed for cleaning this afternoon.','TTS',NULL,NULL,0,'Recorded for manual review. Repeat with natural stress and all words complete.',110),
